/* Build the shell's icon subset from the installed upstream Lucide package. */
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const PUBLIC = path.join(ROOT, 'public');
const OUTPUT = path.join(PUBLIC, 'vendor', 'lucide-subset.js');
const EXPECTED_VERSION = '1.45.0';

function toPascalCase(name) {
  return name.replace(/(^|[-_\s]+)([a-z0-9])/g, (_, separator, char) => char.toUpperCase());
}

function collectIconNames() {
  const names = new Set();
  // Public modules share the shell's window.lucide. Include all their literal
  // icons, not only icons visible on the initial generation page.
  for (const file of fs.readdirSync(PUBLIC).sort()) {
    if (!/\.(?:html|m?js)$/.test(file)) continue;
    const source = fs.readFileSync(path.join(PUBLIC, file), 'utf8');
    for (const match of source.matchAll(/data-lucide\s*=\s*(["'])(.*?)\1/g)) {
      const value = match[2];
      if (/^[a-z][a-z0-9-]*$/.test(value)) names.add(value);
      else if (value.includes('${')) {
        // Dynamic templates select an icon by kind or result status.
        for (const literal of value.matchAll(/['"]([a-z][a-z0-9-]*)['"]/g)) names.add(literal[1]);
      }
    }
    for (const match of source.matchAll(/\bicon\s*:\s*['"]([a-z][a-z0-9-]*)['"]/g)) names.add(match[1]);
  }
  return [...names].sort();
}

function buildBundle() {
  const packageRoot = path.dirname(require.resolve('lucide/package.json'));
  const metadata = JSON.parse(fs.readFileSync(path.join(packageRoot, 'package.json'), 'utf8'));
  if (metadata.version !== EXPECTED_VERSION) throw new Error(`Review the Lucide runtime before upgrading from ${EXPECTED_VERSION}.`);
  const upstream = require('lucide');
  const names = collectIconNames();
  const icons = {};
  for (const name of names) {
    const exportName = toPascalCase(name);
    if (!upstream.icons[exportName]) throw new Error(`Unknown Lucide icon: ${name}`);
    icons[exportName] = upstream.icons[exportName];
  }

  // Keep the upstream DOM/attributes/accessibility implementation unchanged.
  // Removing its ESM import/export statements allows the same small runtime to
  // expose the existing window.lucide contract without adding a bundler.
  const runtimeFiles = [
    'defaultAttributes.mjs',
    'createElement.mjs',
    'shared/src/utils/mergeClasses.mjs',
    'shared/src/utils/hasA11yProp.mjs',
    'shared/src/utils/toCamelCase.mjs',
    'shared/src/utils/toPascalCase.mjs',
    'replaceElement.mjs',
    'lucide.mjs',
  ];
  const runtime = runtimeFiles.map(file => fs.readFileSync(path.join(packageRoot, 'dist', 'esm', file), 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/^(?:import |export |\/\/# sourceMappingURL=).*$/gm, '')
    .replace(/\n{3,}/g, '\n\n').trim()).join('\n\n');
  const license = fs.readFileSync(path.join(packageRoot, 'LICENSE'), 'utf8').trim();
  const source = `/**\n * @license lucide v${metadata.version} - ISC\n * Generated by scripts/build-lucide-subset.cjs; do not edit.\n *\n${license.split(/\r?\n/).map(line => ` * ${line}`).join('\n')}\n */\n(function (global) {\n'use strict';\n${runtime}\n\nconst icons = Object.freeze(${JSON.stringify(icons)});\nconst api = { ...icons, icons, createElement, createIcons: (options = {}) => createIcons({ icons, ...options }) };\nglobal.lucide = api;\n})(typeof globalThis !== 'undefined' ? globalThis : window);\n`;
  return { source, names, icons };
}

if (require.main === module) {
  const result = buildBundle();
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(OUTPUT) || fs.readFileSync(OUTPUT, 'utf8') !== result.source) {
      console.error('The shell icon subset is stale. Run node scripts/build-lucide-subset.cjs.');
      process.exitCode = 1;
    }
  } else {
    fs.writeFileSync(OUTPUT, result.source);
  }
  const fullBytes = fs.statSync(path.join(PUBLIC, 'vendor', 'lucide.min.js')).size;
  const subsetBytes = Buffer.byteLength(result.source);
  console.log(JSON.stringify({ icons: result.names.length, fullBytes, subsetBytes, savedBytes: fullBytes - subsetBytes }));
}

module.exports = { buildBundle, collectIconNames, OUTPUT };
